import re

def evaluate(text):
    tokens = re.findall(r'\d+|[+*()-]', text)
    pos = 0
    def parse_factor():
        nonlocal pos
        if tokens[pos] == '(':
            pos += 1
            val = parse_expr()
            if tokens[pos] != ')': raise SyntaxError
            pos += 1
            return val
        val = int(tokens[pos]); pos += 1; return val
    def parse_term():
        nonlocal pos
        val = parse_factor()
        while pos < len(tokens) and tokens[pos] == '*':
            pos += 1; val *= parse_factor()
        return val
    def parse_expr():
        nonlocal pos
        val = parse_term()
        while pos < len(tokens) and tokens[pos] in '+-':
            op = tokens[pos]; pos += 1
            if op == '+': val += parse_term()
            else: val -= parse_term()
        return val
    res = parse_expr()
    if pos != len(tokens): raise SyntaxError
    return res

def to_postfix(text):
    tokens = re.findall(r'\d+|[+*()-]', text)
    pos = 0
    def parse_factor():
        nonlocal pos
        if tokens[pos] == '(':
            pos += 1; res = parse_expr(); pos += 1; return res
        val = tokens[pos]; pos += 1; return val
    def parse_term():
        nonlocal pos
        res = parse_factor()
        while pos < len(tokens) and tokens[pos] == '*':
            op = tokens[pos]; pos += 1; res += ' ' + parse_factor() + ' ' + op
        return res
    def parse_expr():
        nonlocal pos
        res = parse_term()
        while pos < len(tokens) and tokens[pos] in '+-':
            op = tokens[pos]; pos += 1; res += ' ' + parse_term() + ' ' + op
        return res
    res = parse_expr()
    if pos != len(tokens): raise SyntaxError
    return ' '.join(res.split())

def is_valid(text):
    try: evaluate(text); return True
    except: return False

print(evaluate("2 + 3 * 4"))

